@startuml

class Employee {
  + Ssn : int
  + FirstName : string
  + LastName : string
}

abstract class CreativeEmployee {
  + OscarWinner : boolean
}

class Director {}
class Actor {}

class Technician {
  + FieldOfActivity : string
}

class FilmSet {
  + Location : string
  + Films : Film[]
}

class Film {
  + Title : string
  + ReleaseYear : int
  + Genre : Genre
}

enum Genre {
  Thriller
  Action
  Horror
  Comedy
}

class Screenwriter {
  + Name : string
  + MostSuccessfulFilm : Film
}

class Screenplay {
  + Title : string
  + Version : string
  + Date : date
  + NumberOfScenes : int
  + Plot : string
  + BasedOnNovel : Novel
  + BasedOnConcept : Concept
}

class Novel {
  + Title : string
  + Author : Person
}

class Concept {}

Employee "1" -- "*" FilmSet
FilmSet "1..*" Film
Film "1" -- "0..*" Actor
Film "1" -- "1" Screenplay
Screenwriter "1" -- "*" Screenplay
Screenplay "1" -- "1" Film
Actor "1" -- "*" Screenplay

@enduml

